// (Data/Patches/Plugin presets/Generators/Fruity Envelope Controller; numbers only, see docs/research/gen/envctrl.md).
// Generated by a script from the decoded states; shapes and articulators shared between presets are stored once.

/** A point: position (envelope units), value 0..1, tension -1..1, FL's point mode tag. */
export type RawPt = [number, number, number, number];
/** An envelope: points, flags (bit 0 tempo-based time, bit 1 global LFO phase), enabled, D / L / S marker point indexes (-1 = none). */
export interface RawShape { p: RawPt[]; f: number; e: number; d: number; l: number; s: number }
/** An articulator: envelope, LFO modifier envelope, the five mapping envelopes (key, velocity, Mod X, Mod Y, random), polarity (1 bipolar sum / 0 unipolar product). */
export type RawArt = readonly [RawShape, RawShape, RawShape[], number];
export interface RawPreset { name: string; params: number[]; arts: RawArt[]; lo: number[]; hi: number[]; cont: number; sel: number; src: number }

